// Package claim records which design generated which file, so several
// manifests writing into one tree can tell their own output from a
// sibling's.
//
// Every file craftgo REGENERATES - the ones carrying the "DO NOT EDIT"
// header - is claimed by the design it came from. A run reads the claims
// filed in each directory it writes into: a file another design already
// claims is a collision, because the second run would overwrite the first
// and the order of the build would decide what the directory holds. Two
// runs of the SAME design source file one claim and never collide, which
// is what lets several deployables generate from one design.
//
// Gen-once scaffolds are outside this. They are written when missing and
// never overwritten, so two manifests cannot clobber one.
package claim

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"os"
	"path"
	"path/filepath"
	"sort"
	"strings"
)

// Dir holds one record per design writing into an output directory. The
// leading dot keeps it out of the Go package the directory otherwise is.
const Dir = ".craftgo-gen"

// Output is one directory a run writes into, with the regenerated files
// it puts there. Root is where the claim is filed: the directory two
// manifests writing one file both compute, whatever their project roots.
type Output struct {
	Root  string
	Files []string
}

// Record is one design's claim on an output directory: the files its last
// run produced, relative to that directory.
type Record struct {
	// Design is the design folder the claim came from, relative to the
	// output directory. It is the claim's identity: two runs of one
	// design file one record, whichever manifest drove them.
	Design string `json:"design"`
	// Manifests are the folders of the manifests that file this claim,
	// relative to the output directory and sorted. One design may be
	// generated by several - that is what a projection is - so the
	// diagnostic can name the file the user has to edit, whichever
	// manifest ran last.
	Manifests []string `json:"manifests"`
	// Files are slash-separated paths relative to the output directory.
	Files []string `json:"files"`
}

// Key is the design folder as a claim records it: relative to the output
// directory the claim is filed in. The output is what the manifests
// sharing it agree on - their project roots need not be the same - and a
// relative path survives a checkout elsewhere.
func Key(root, designRoot string) string {
	rel, err := filepath.Rel(root, designRoot)
	if err != nil {
		return filepath.ToSlash(designRoot)
	}
	return filepath.ToSlash(rel)
}

// Name is the file a design claims through. The key is a path, so a
// checkout on another machine files the same claim; two designs sharing a
// basename are told apart by the hash.
func Name(key string) string {
	slug := filepath.Base(filepath.Clean(key))
	slug = strings.Map(func(r rune) rune {
		switch {
		case r >= 'a' && r <= 'z', r >= '0' && r <= '9', r == '-', r == '_':
			return r
		case r >= 'A' && r <= 'Z':
			return r + ('a' - 'A')
		}
		return '-'
	}, slug)
	sum := sha256.Sum256([]byte(filepath.ToSlash(key)))
	return slug + "-" + hex.EncodeToString(sum[:4]) + ".json"
}

// Inside reports whether a recorded path stays under the output
// directory. A claim is committed, so a bad merge or a hand edit can put
// `../..` in one; every path is checked on read and on write, or a prune
// would delete outside the tree it owns.
func Inside(rel string) bool {
	clean := path.Clean(strings.ReplaceAll(rel, "\\", "/"))
	return clean != ".." && !strings.HasPrefix(clean, "../") && !path.IsAbs(clean)
}

// Read returns every claim filed against root, keyed by file name. An
// unreadable or malformed record is skipped, and a path escaping root is
// dropped: either can only make a prune more cautious.
func Read(root string) map[string]Record {
	out := map[string]Record{}
	entries, err := os.ReadDir(filepath.Join(root, Dir))
	if err != nil {
		return out
	}
	for _, e := range entries {
		if e.IsDir() || filepath.Ext(e.Name()) != ".json" {
			continue
		}
		body, err := os.ReadFile(filepath.Join(root, Dir, e.Name()))
		if err != nil {
			continue
		}
		var rec Record
		if json.Unmarshal(body, &rec) != nil {
			continue
		}
		files := rec.Files[:0]
		for _, f := range rec.Files {
			if Inside(f) {
				files = append(files, f)
			}
		}
		rec.Files = files
		out[e.Name()] = rec
	}
	return out
}

// Live drops a claim whose design folder is gone. The key is a path, so
// renaming or deleting a design leaves a record that protects files
// nothing produces any more and that nothing can report.
//
// A record naming no design cannot be checked, and unverifiable is not
// the same as dead: it is kept, so a run without a design root still
// prunes what it wrote.
func Live(records map[string]Record, root string) map[string]Record {
	out := make(map[string]Record, len(records))
	for name, rec := range records {
		if rec.Design != "" {
			if fi, err := os.Stat(filepath.Join(root, filepath.FromSlash(rec.Design))); err != nil || !fi.IsDir() {
				continue
			}
		}
		out[name] = rec
	}
	return out
}

// Foreign returns, for every live claim against root other than `mine`,
// the absolute path of each file it holds mapped to the record holding
// it.
func Foreign(root, mine string) map[string]Record {
	out := map[string]Record{}
	for name, rec := range Live(Read(root), root) {
		if name == mine {
			continue
		}
		for _, f := range rec.Files {
			out[filepath.Join(root, filepath.FromSlash(f))] = rec
		}
	}
	return out
}

// Write records the files a design produced under root. A design that
// produces nothing there drops its record instead of filing an empty one.
//
// The manifest joins the record's set rather than replacing it, so which
// deployable of a shared design ran last does not change the file.
func Write(root, name, key, manifest string, files []string) error {
	rel := make([]string, 0, len(files))
	for _, f := range files {
		r, err := filepath.Rel(root, f)
		if err != nil {
			continue
		}
		if slash := filepath.ToSlash(r); Inside(slash) {
			rel = append(rel, slash)
		}
	}
	dir := filepath.Join(root, Dir)
	if len(rel) == 0 {
		if err := os.Remove(filepath.Join(dir, name)); err != nil && !os.IsNotExist(err) {
			return err
		}
		// The directory goes with the last claim in it, so a design that
		// stops writing here leaves nothing behind.
		if entries, err := os.ReadDir(dir); err == nil && len(entries) == 0 {
			_ = os.Remove(dir)
		}
		return nil
	}
	sort.Strings(rel)
	body, err := json.MarshalIndent(Record{
		Design:    filepath.ToSlash(key),
		Manifests: manifestSet(root, Read(root)[name], manifest),
		Files:     rel,
	}, "", "  ")
	if err != nil {
		return err
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	return os.WriteFile(filepath.Join(dir, name), append(body, '\n'), 0o644)
}

// manifestSet adds this run's manifest to the ones a record already
// names, dropping any whose folder is gone. The result is sorted, so two
// deployables of one design file the same record whichever order they
// run in.
func manifestSet(root string, prev Record, manifest string) []string {
	seen := map[string]bool{filepath.ToSlash(manifest): true}
	for _, m := range prev.Manifests {
		if fi, err := os.Stat(filepath.Join(root, filepath.FromSlash(m))); err == nil && fi.IsDir() {
			seen[m] = true
		}
	}
	out := make([]string, 0, len(seen))
	for m := range seen {
		out = append(out, m)
	}
	sort.Strings(out)
	return out
}

// generatedHeaders open the files craftgo rewrites on every run: the Go
// header, and the one the YAML documents carry. A gen-once scaffold opens
// with a different line, so it is never claimed and never pruned.
var generatedHeaders = []string{
	"// Code generated by craftgo. DO NOT EDIT.",
	"# Generated by craftgo. DO NOT EDIT.",
}

// Generated reports whether the file at path is one craftgo regenerates.
// A missing or unreadable file is not, so a prune can ask this question
// instead of stat-ing first.
func Generated(path string) bool {
	body, err := os.ReadFile(path)
	if err != nil {
		return false
	}
	for _, header := range generatedHeaders {
		if strings.HasPrefix(string(body), header) {
			return true
		}
	}
	return false
}
